CREATE TABLE `station` (`id` DECIMAL(18,2), `name` VARCHAR(100), `lat` DECIMAL(18,2), `long` DECIMAL(18,2), `dock_count` DECIMAL(18,2), `city` VARCHAR(100), `installation_date` VARCHAR(100));
CREATE TABLE `status` (`station_id` DECIMAL(18,2), `bikes_available` DECIMAL(18,2), `docks_available` DECIMAL(18,2), `time` VARCHAR(100));
CREATE TABLE `trip` (`id` DECIMAL(18,2), `duration` DECIMAL(18,2), `start_date` VARCHAR(100), `start_station_name` VARCHAR(100), `start_station_id` DECIMAL(18,2), `end_date` VARCHAR(100), `end_station_name` VARCHAR(100), `end_station_id` DECIMAL(18,2), `bike_id` DECIMAL(18,2), `subscription_type` VARCHAR(100), `zip_code` DECIMAL(18,2));
CREATE TABLE `weather` (`date` VARCHAR(100), `max_temperature_f` DECIMAL(18,2), `mean_temperature_f` DECIMAL(18,2), `min_temperature_f` DECIMAL(18,2), `max_dew_point_f` DECIMAL(18,2), `mean_dew_point_f` DECIMAL(18,2), `min_dew_point_f` DECIMAL(18,2), `max_humidity` DECIMAL(18,2), `mean_humidity` DECIMAL(18,2), `min_humidity` DECIMAL(18,2), `max_sea_level_pressure_inches` DECIMAL(18,2), `mean_sea_level_pressure_inches` DECIMAL(18,2), `min_sea_level_pressure_inches` DECIMAL(18,2), `max_visibility_miles` DECIMAL(18,2), `mean_visibility_miles` DECIMAL(18,2), `min_visibility_miles` DECIMAL(18,2), `max_wind_Speed_mph` DECIMAL(18,2), `mean_wind_speed_mph` DECIMAL(18,2), `max_gust_speed_mph` DECIMAL(18,2), `precipitation_inches` DECIMAL(18,2), `cloud_cover` DECIMAL(18,2), `events` VARCHAR(100), `wind_dir_degrees` DECIMAL(18,2), `zip_code` DECIMAL(18,2));
